-- S-04: recurring expenses. A definition materializes one real expenses row per month (fixed horizon, no scheduler).
-- Every policy filters by (select public.current_household_id()) - see context/foundation/lessons.md.
-- expenses gains a DELETE policy narrowed to rows generated by a definition (recurring_expense_id is not null), so
-- stopping / re-generating can delete future entries. Manual rows stay delete-protected until S-06.
--
-- Rules (all dates in Europe/Warsaw, computed in the database so every function agrees on "today"):
--   * slots run from start_month (the month the definition was created) to end_month, one row per month;
--   * a row's date is day_of_month clamped to the length of that month, computed from the base day for every month
--     (31 -> 31 Jan, 28 Feb, 31 Mar - no drift);
--   * "future" entries are rows dated after today; stop deletes them, an amount change deletes and re-creates them;
--   * the horizon covers at most 24 months counting the current one (months_left <= 23), for create and extend alike.

create table public.recurring_expenses (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null default public.current_household_id() references public.households (id) on delete cascade,
  category_id uuid not null,
  amount_minor bigint not null check (amount_minor > 0 and amount_minor <= 9999999999),
  day_of_month smallint not null check (day_of_month between 1 and 31),
  start_month date not null check (extract(day from start_month) = 1),
  end_month date not null check (extract(day from end_month) = 1),
  stopped_at timestamptz,
  reminder_dismissed_at timestamptz,
  created_at timestamptz not null default now(),
  check (end_month >= start_month),
  -- Target of the composite foreign key on expenses.
  unique (household_id, id),
  -- Same reasoning as on expenses: a plain FK on category_id would be checked without RLS.
  -- ON DELETE CASCADE: a stopped definition stays in the table (soft delete) and is invisible to the user, so without
  -- it a category with no expenses left could never be deleted. A category that still has entries stays protected by
  -- the foreign key from expenses.
  foreign key (household_id, category_id) references public.categories (household_id, id) on delete cascade
);

-- Two identical active definitions from the same month are almost certainly a double submit (two clicks, two tabs):
-- they would double the monthly totals, and stopping one would leave the other running. The API maps 23505 to a message.
create unique index recurring_expenses_active_unique_idx
  on public.recurring_expenses (household_id, category_id, amount_minor, day_of_month, start_month)
  where stopped_at is null;

alter table public.expenses add column recurring_expense_id uuid;
-- Definitions are stopped (stopped_at), never deleted, so no ON DELETE action is needed. A null recurring_expense_id
-- (a manual entry) skips the check (MATCH SIMPLE).
alter table public.expenses
  add foreign key (household_id, recurring_expense_id) references public.recurring_expenses (household_id, id);

create index expenses_recurring_expense_idx on public.expenses (recurring_expense_id, spent_on)
  where recurring_expense_id is not null;

alter table public.recurring_expenses enable row level security;

create policy "recurring_expenses_select_own" on public.recurring_expenses
  for select to authenticated
  using (household_id = (select public.current_household_id()));

create policy "recurring_expenses_insert_own" on public.recurring_expenses
  for insert to authenticated
  with check (household_id = (select public.current_household_id()));

create policy "recurring_expenses_update_own" on public.recurring_expenses
  for update to authenticated
  using (household_id = (select public.current_household_id()))
  with check (household_id = (select public.current_household_id()));

create policy "expenses_delete_generated" on public.expenses
  for delete to authenticated
  using (household_id = (select public.current_household_id()) and recurring_expense_id is not null);

-- ===== Pure helpers =====
-- SECURITY INVOKER functions run with the caller's privileges, so the helpers they call must be executable by
-- authenticated. These read no tables.

-- Today in Warsaw: Workers run in UTC, and so does the database session clock unless converted.
create function public.warsaw_today()
returns date
language sql
stable
security invoker
set search_path = ''
as $$
  select (now() at time zone 'Europe/Warsaw')::date;
$$;

-- Date of the entry for p_month (any day of that month): p_day clamped to the length of the month.
create function public.recurring_slot_date(p_month date, p_day int)
returns date
language sql
immutable
security invoker
set search_path = ''
as $$
  select m.first_day + (least(p_day, ((m.first_day + interval '1 month')::date - m.first_day)) - 1)
  from (select p_month - (extract(day from p_month)::int - 1) as first_day) m;
$$;

-- Whole calendar months from p_from's month to p_to's month (negative when p_to is earlier).
create function public.recurring_month_diff(p_from date, p_to date)
returns int
language sql
immutable
security invoker
set search_path = ''
as $$
  select (extract(year from p_to)::int - extract(year from p_from)::int) * 12
       + extract(month from p_to)::int - extract(month from p_from)::int;
$$;

-- ===== Operations =====
-- All SECURITY INVOKER: household_id defaults to the caller's household and RLS scopes everything else. Each
-- operation is one transaction, so a failed regenerate never leaves a half-deleted horizon behind.
-- Operations on an existing definition lock its row (serializes two tabs / double clicks) and raise P0002 when it
-- does not exist for the caller, belongs to another household, or is stopped.

create function public.create_recurring_expense(p_category_id uuid, p_amount_minor bigint, p_day int, p_months int)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_today date := public.warsaw_today();
  v_start date := v_today - (extract(day from v_today)::int - 1);
  v_id uuid;
begin
  if p_months is null or p_months not between 1 and 24 then
    raise exception 'p_months must be between 1 and 24' using errcode = '22023';
  end if;

  insert into public.recurring_expenses (category_id, amount_minor, day_of_month, start_month, end_month)
  values (p_category_id, p_amount_minor, p_day, v_start, (v_start + make_interval(months => p_months - 1))::date)
  returning id into v_id;

  insert into public.expenses (category_id, amount_minor, spent_on, recurring_expense_id)
  select p_category_id, p_amount_minor,
         public.recurring_slot_date((v_start + make_interval(months => g))::date, p_day), v_id
  from generate_series(0, p_months - 1) as g;

  return v_id;
end;
$$;

-- Deletes the future entries and re-creates them at the new amount: only slots dated after today, so entries dated
-- today or earlier keep their old amount.
create function public.update_recurring_expense_amount(p_id uuid, p_amount_minor bigint)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_today date := public.warsaw_today();
  v_current date := v_today - (extract(day from v_today)::int - 1);
  v_def public.recurring_expenses;
begin
  select * into v_def from public.recurring_expenses where id = p_id and stopped_at is null for no key update;
  if not found then
    raise exception 'recurring expense not found' using errcode = 'P0002';
  end if;

  update public.recurring_expenses set amount_minor = p_amount_minor where id = p_id;
  delete from public.expenses where recurring_expense_id = p_id and spent_on > v_today;

  insert into public.expenses (category_id, amount_minor, spent_on, recurring_expense_id)
  select v_def.category_id, p_amount_minor, s.spent_on, p_id
  from (
    select public.recurring_slot_date((v_def.start_month + make_interval(months => g))::date, v_def.day_of_month) as spent_on
    -- Slots before the current month are all dated before today, so the series starts at the current month.
    from generate_series(
      greatest(0, public.recurring_month_diff(v_def.start_month, v_current)),
      public.recurring_month_diff(v_def.start_month, v_def.end_month)
    ) as g
  ) s
  where s.spent_on > v_today;
end;
$$;

-- Appends p_months slots after the horizon. A lapsed definition (end_month before the current month) restarts at the
-- current month, so nothing is created for past months. The horizon may cover at most 24 months counting the current one.
create function public.extend_recurring_expense(p_id uuid, p_months int)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_today date := public.warsaw_today();
  v_current date := v_today - (extract(day from v_today)::int - 1);
  v_def public.recurring_expenses;
  v_first date;
  v_new_end date;
begin
  if p_months is null or p_months not between 1 and 24 then
    raise exception 'p_months must be between 1 and 24' using errcode = '22023';
  end if;

  select * into v_def from public.recurring_expenses where id = p_id and stopped_at is null for no key update;
  if not found then
    raise exception 'recurring expense not found' using errcode = 'P0002';
  end if;

  v_first := greatest((v_def.end_month + make_interval(months => 1))::date, v_current);
  v_new_end := (v_first + make_interval(months => p_months - 1))::date;
  if public.recurring_month_diff(v_current, v_new_end) > 23 then
    raise exception 'the horizon cannot cover more than 24 months from the current one' using errcode = '22023';
  end if;

  update public.recurring_expenses set end_month = v_new_end, reminder_dismissed_at = null where id = p_id;

  insert into public.expenses (category_id, amount_minor, spent_on, recurring_expense_id)
  select v_def.category_id, v_def.amount_minor,
         public.recurring_slot_date((v_first + make_interval(months => g))::date, v_def.day_of_month), p_id
  from generate_series(0, p_months - 1) as g;
end;
$$;

-- Soft delete: the definition disappears from the list, the entries dated after today go, earlier ones stay.
create function public.stop_recurring_expense(p_id uuid)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_today date := public.warsaw_today();
begin
  perform 1 from public.recurring_expenses where id = p_id and stopped_at is null for no key update;
  if not found then
    raise exception 'recurring expense not found' using errcode = 'P0002';
  end if;

  delete from public.expenses where recurring_expense_id = p_id and spent_on > v_today;
  update public.recurring_expenses set stopped_at = now() where id = p_id;
end;
$$;

create function public.dismiss_recurring_reminder(p_id uuid)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
begin
  update public.recurring_expenses set reminder_dismissed_at = now() where id = p_id and stopped_at is null;
  if not found then
    raise exception 'recurring expense not found' using errcode = 'P0002';
  end if;
end;
$$;

-- Active and lapsed definitions of the caller's household, newest first. months_left counts calendar months from the
-- current month to end_month (negative = lapsed); remind is true while 0 or 1 month is left and nobody dismissed it.
create function public.list_recurring_expenses()
returns table (
  id uuid,
  category_id uuid,
  category_name text,
  category_archived boolean,
  amount_minor bigint,
  day_of_month int,
  start_month date,
  end_month date,
  months_left int,
  remind boolean
)
language sql
stable
security invoker
set search_path = ''
as $$
  select s.id, s.category_id, s.category_name, s.category_archived, s.amount_minor, s.day_of_month, s.start_month,
         s.end_month, s.months_left,
         (s.reminder_dismissed_at is null and s.months_left between 0 and 1) as remind
  from (
    select r.id, r.category_id, c.name as category_name, c.archived_at is not null as category_archived,
           r.amount_minor, r.day_of_month::int as day_of_month, r.start_month, r.end_month, r.created_at,
           r.reminder_dismissed_at, public.recurring_month_diff(public.warsaw_today(), r.end_month) as months_left
    from public.recurring_expenses r
    join public.categories c on c.household_id = r.household_id and c.id = r.category_id
    where r.stopped_at is null
  ) s
  order by s.created_at desc, s.id;
$$;

-- Supabase grants EXECUTE on new public functions to anon/authenticated (see 20261008200524_revoke_function_execute).
revoke execute on function public.warsaw_today() from public, anon;
grant execute on function public.warsaw_today() to authenticated;
revoke execute on function public.recurring_slot_date(date, int) from public, anon;
grant execute on function public.recurring_slot_date(date, int) to authenticated;
revoke execute on function public.recurring_month_diff(date, date) from public, anon;
grant execute on function public.recurring_month_diff(date, date) to authenticated;
revoke execute on function public.create_recurring_expense(uuid, bigint, int, int) from public, anon;
grant execute on function public.create_recurring_expense(uuid, bigint, int, int) to authenticated;
revoke execute on function public.update_recurring_expense_amount(uuid, bigint) from public, anon;
grant execute on function public.update_recurring_expense_amount(uuid, bigint) to authenticated;
revoke execute on function public.extend_recurring_expense(uuid, int) from public, anon;
grant execute on function public.extend_recurring_expense(uuid, int) to authenticated;
revoke execute on function public.stop_recurring_expense(uuid) from public, anon;
grant execute on function public.stop_recurring_expense(uuid) to authenticated;
revoke execute on function public.dismiss_recurring_reminder(uuid) from public, anon;
grant execute on function public.dismiss_recurring_reminder(uuid) to authenticated;
revoke execute on function public.list_recurring_expenses() from public, anon;
grant execute on function public.list_recurring_expenses() to authenticated;
